INSERT INTO `profiles` (`id`, `userId`, `firstName`, `lastName`, `headline`, `bio`, `avatarUrl`, `phone`, `address`, `city`, `country`, `postalCode`, `website`, `github`, `linkedin`, `twitter`, `createdAt`, `updatedAt`) VALUES ('bf3d346f-db03-4c60-9d17-ba6cdd79f10a', 'e8850439-da34-4a0f-86a0-46f58f1a7b04', 'Alex', 'Morgan', 'Full-Stack Software Engineer & Open Source Contributor', 'Passionate software engineer building resilient distributed systems and intuitive user interfaces. Over 5 years of experience in TypeScript, React, and cloud architectures.', NULL, '+1 (555) 019-2834', NULL, 'San Francisco', 'United States', NULL, 'https://alexmorgan.dev', 'https://github.com/alexmorgan', 'https://linkedin.com/in/alexmorgan', NULL, NOW(), NOW()) ON DUPLICATE KEY UPDATE `headline`=VALUES(`headline`), `bio`=VALUES(`bio`);
INSERT INTO `cvs` (`id`, `userId`, `templateId`, `title`, `slug`, `content`, `styling`, `createdAt`, `updatedAt`) VALUES ('dd431e6d-ec51-4065-ad6c-26bdbd4c20b2', 'e8850439-da34-4a0f-86a0-46f58f1a7b04', '796d42df-54c6-4629-b401-abc3111fbee9', 'Md. Rasel Aktar — Frontend Developer CV', NULL, '{"personalInfo":{"fullName":"MD. RASEL AKTAR","headline":"Frontend Developer | React.js | Next.js | Angular | TypeScript","email":"raselcse.dev@gmail.com","phone":"+8801768297822","city":"Dhaka","country":"Bangladesh","website":"https://personal-website-six-chi-23.vercel.app/","github":"https://github.com/raselcsedev","linkedin":"https://linkedin.com/in/md-rasel-1a9957174/"},"summary":"Frontend Developer with 4 years of professional experience building production web applications with React.js, Next.js, Angular, TypeScript, and JavaScript (ES6+). Delivered enterprise ERP systems, multi-vendor eCommerce platforms, and AI-powered products used by real businesses. Strong in REST and GraphQL API integration, reusable component architecture, state management, payment gateway integration, and responsive, multilingual UI. Works effectively in Agile, cross-functional teams.","experiences":[{"id":"exp-1","company":"Digital Intelligence System Ltd.","position":"Frontend Developer","location":"Dhaka, Bangladesh","startDate":"11/2023","endDate":"","current":true,"description":"• Build and maintain enterprise ERP applications (Base ERP, Hatil ERP) using Angular, TypeScript, RxJS, Tailwind CSS, and TanStack Query.\\n• Delivered frontend workflows across Sales, Purchase, and Inventory modules, including Sales Bills, Warehouse Bills, Repair Service, Dealer Money Receipts, Raw Material Purchases, and Finished Goods Receipts.\\n• Migrated legacy React, AngularJS, and ASP.NET WebForms pages to Angular 17+ standalone components across sales, inventory, procurement, HR, and admin modules.\\n• Integrated backend REST APIs and developed reusable, responsive UI components, including a configurable data-table component, for data-heavy enterprise workflows.\\n• Develop multi-vendor and single-vendor eCommerce platforms (Quick eCommerce, Retail Master) using Next.js, TypeScript, Tailwind CSS, and TanStack Query.\\n• Built and maintain 10+ industry-specific storefront themes (grocery, medicine, furniture, footwear, watches, lifestyle) with dynamic theming.\\n• Integrated bKash and SSLCommerz payment gateways and implemented guest checkout, cash-on-delivery, multilingual (next-intl), and multi-currency functionality.\\n• Developed Bizpost AI, an AI-powered social media content generation platform (Next.js, TypeScript) for creating Facebook, TikTok, and LinkedIn content."},{"id":"exp-2","company":"Gain Solutions Ltd.","position":"JavaScript Developer","location":"Dhaka, Bangladesh","startDate":"09/2022","endDate":"10/2023","current":false,"description":"• Developed frontend features for Unite Living, a house rental management system, using React.js, GraphQL, and Apollo Client.\\n• Implemented CRUD functionality and integrated GraphQL APIs for application data management.\\n• Built reusable, maintainable UI components that improved interface consistency across the application.\\n• Collaborated with cross-functional team members in an Agile environment to deliver production-ready features."}],"educations":[{"id":"edu-1","institution":"University of South Asia","degree":"B.Sc. in Computer Science and Engineering","field":"Dhaka, Bangladesh","startDate":"05/2017","endDate":"04/2021"}],"skills":[{"id":"sk-1","name":"JavaScript (ES6+)","category":"Languages"},{"id":"sk-2","name":"TypeScript","category":"Languages"},{"id":"sk-3","name":"HTML5","category":"Languages"},{"id":"sk-4","name":"CSS3 / Sass","category":"Languages"},{"id":"sk-5","name":"React.js","category":"Frameworks & Libraries"},{"id":"sk-6","name":"Next.js","category":"Frameworks & Libraries"},{"id":"sk-7","name":"Angular (standalone)","category":"Frameworks & Libraries"},{"id":"sk-8","name":"RxJS","category":"Frameworks & Libraries"},{"id":"sk-9","name":"Redux Toolkit","category":"Frameworks & Libraries"},{"id":"sk-10","name":"TanStack Query","category":"Frameworks & Libraries"},{"id":"sk-11","name":"Tailwind CSS","category":"Styling & UI"},{"id":"sk-12","name":"Bootstrap","category":"Styling & UI"},{"id":"sk-13","name":"shadcn/ui","category":"Styling & UI"},{"id":"sk-14","name":"Aceternity UI","category":"Styling & UI"},{"id":"sk-15","name":"Responsive Design","category":"Styling & UI"},{"id":"sk-16","name":"REST APIs","category":"APIs & Integrations"},{"id":"sk-17","name":"GraphQL / Apollo","category":"APIs & Integrations"},{"id":"sk-18","name":"OpenAI API","category":"APIs & Integrations"},{"id":"sk-19","name":"bKash / SSLCommerz","category":"APIs & Integrations"},{"id":"sk-20","name":"Git & GitHub","category":"Tools & Platforms"},{"id":"sk-21","name":"Postman","category":"Tools & Platforms"},{"id":"sk-22","name":"Chrome DevTools","category":"Tools & Platforms"},{"id":"sk-23","name":"Vercel / Netlify","category":"Tools & Platforms"},{"id":"sk-24","name":"Node.js / Express.js","category":"Backend Familiarity"},{"id":"sk-25","name":"MySQL / MongoDB","category":"Backend Familiarity"},{"id":"sk-26","name":"ASP.NET Core Web API","category":"Backend Familiarity"},{"id":"sk-27","name":"Agile / Scrum","category":"Practices"},{"id":"sk-28","name":"Reusable Components","category":"Practices"},{"id":"sk-29","name":"Code Review","category":"Practices"}],"projects":[{"id":"proj-1","title":"CareerCraft","technologies":"Next.js 14, NestJS, TypeScript, MySQL, Prisma ORM, Tailwind CSS","description":"• Full-stack CV Builder & Portfolio Platform.\\n• Build professional CVs using beautiful templates with browser-native A4 PDF export.\\n• Publish a personal portfolio site with a unique public URL.\\n• Import an existing CV by uploading a PDF or DOCX file (auto-parsed).\\n• Dark/light themes and custom typography.","url":"https://career-craft.vercel.app","github":"https://github.com/raselcsedev/career-craft"},{"id":"proj-2","title":"AI Content Studio","technologies":"Next.js, TypeScript, MongoDB, OpenAI API, NextAuth, Tailwind CSS","description":"• Built an AI content generation platform for blog posts, emails, code snippets, and image prompts.\\n• Implemented authentication, user management, and role-based access control.\\n• Responsive dashboard with usage analytics and searchable history.","github":"https://github.com/raselcsedev/ai-content-studio"},{"id":"proj-3","title":"RetailPOS","technologies":"Next.js, TypeScript, MongoDB, Mongoose, NextAuth","description":"• Developed a full-stack point-of-sale and inventory management application with barcode generation, tracking, and sales processing.\\n• Built dashboard analytics, thermal receipt printing, and PWA support.","github":"https://github.com/raselcsedev/retail-pos","url":"https://jovial-sable-2db9bd.netlify.app/"}],"languages":[{"id":"lang-1","name":"Bangla","proficiency":"Native"},{"id":"lang-2","name":"English","proficiency":"Full working proficiency"}],"certifications":[]}', '{"primaryColor":"#334155","fontFamily":"Inter","fontSize":"normal","spacing":"normal"}', NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `content`=VALUES(`content`), `styling`=VALUES(`styling`);
INSERT INTO `portfolios` (`id`, `userId`, `templateId`, `title`, `slug`, `bio`, `themeConfig`, `isPublished`, `publishedAt`, `createdAt`, `updatedAt`) VALUES ('d7aa4a7b-2eb7-4cfb-90fa-a51332ff1d70', 'e8850439-da34-4a0f-86a0-46f58f1a7b04', 'c09c7e07-ab38-4223-a60e-7db336455054', 'Md. Rasel Aktar — Developer Portfolio', 'rasel', 'Frontend Developer with 4 years of experience building high-performance web applications, enterprise ERPs, and modern SaaS products.', '{"primaryColor":"#06b6d4","fontFamily":"Inter"}', 1, NOW(), NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `slug`=VALUES(`slug`), `bio`=VALUES(`bio`), `isPublished`=VALUES(`isPublished`);
