INSERT INTO `portfolio_projects` (`id`, `portfolioId`, `title`, `description`, `technologies`, `projectUrl`, `repoUrl`, `imageUrl`, `displayOrder`, `isFeatured`, `createdAt`, `updatedAt`) VALUES ('46e9cab3-19d7-49b1-9b56-484959ff5433', 'd7aa4a7b-2eb7-4cfb-90fa-a51332ff1d70', 'Product Manager', 'Full-stack product CRUD app with Next.js frontend and ASP.NET Core Web API on SQL Server with EF Core migrations and Docker.', '["Next.js","ASP.NET Core","C#","SQL Server","Docker"]', NULL, 'https://github.com/raselcsedev/product-manager', NULL, 1, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `portfolio_projects` (`id`, `portfolioId`, `title`, `description`, `technologies`, `projectUrl`, `repoUrl`, `imageUrl`, `displayOrder`, `isFeatured`, `createdAt`, `updatedAt`) VALUES ('b32dd02f-3962-4d79-a276-6d9339335447', 'd7aa4a7b-2eb7-4cfb-90fa-a51332ff1d70', 'AI Content Studio', 'AI SaaS platform that generates blog posts, emails, code snippets, and image prompts with usage analytics and dark/light themes.', '["Next.js","TypeScript","MongoDB","OpenAI API","NextAuth"]', NULL, 'https://github.com/raselcsedev/ai-content-studio', NULL, 2, 0, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
INSERT INTO `portfolio_projects` (`id`, `portfolioId`, `title`, `description`, `technologies`, `projectUrl`, `repoUrl`, `imageUrl`, `displayOrder`, `isFeatured`, `createdAt`, `updatedAt`) VALUES ('cfad718c-8ba6-41f8-8ee5-949ec7399817', 'd7aa4a7b-2eb7-4cfb-90fa-a51332ff1d70', 'CareerCraft', 'Full-stack CV Builder & Portfolio Platform. Build CVs, export A4 PDFs, import documents, and publish personal portfolio sites with role-based auth.', '["Next.js 14","NestJS","TypeScript","MySQL","Prisma","Tailwind CSS"]', 'https://career-craft.vercel.app', 'https://github.com/raselcsedev/career-craft', NULL, 0, 1, NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);
